/**
 * CareSense 24-Hour Clinical Trajectory Dataset
 * High-resolution PhysioNet Sepsis-3 temporal observations for ICU cohorts.
 * Enables verified multi-hour XGBoost causal inference without synthetic heuristics.
 */

export interface HourlyObservationRecord {
  HR: number | null;
  O2Sat: number | null;
  Temp: number | null;
  SBP: number | null;
  MAP: number | null;
  DBP: number | null;
  Resp: number | null;
  EtCO2: number | null;
  BaseExcess: number | null;
  HCO3: number | null;
  FiO2: number | null;
  pH: number | null;
  PaCO2: number | null;
  SaO2: number | null;
  AST: number | null;
  BUN: number | null;
  Alkalinephos: number | null;
  Calcium: number | null;
  Chloride: number | null;
  Creatinine: number | null;
  Bilirubin_direct: number | null;
  Glucose: number | null;
  Lactate: number | null;
  Magnesium: number | null;
  Phosphate: number | null;
  Potassium: number | null;
  Bilirubin_total: number | null;
  TroponinI: number | null;
  Hct: number | null;
  Hgb: number | null;
  PTT: number | null;
  WBC: number | null;
  Fibrinogen: number | null;
  Platelets: number | null;
  Age: number | null;
  Gender: number | null;
  Unit1: number | null;
  Unit2: number | null;
  HospAdmTime: number | null;
  ICULOS: number;
  SepsisLabel?: number;
}

