/**
 * Dynamic in-memory cache for dynamically generated patient histories
 */
const DYNAMIC_PATIENT_HISTORIES: Record<string, HourlyObservationRecord[]> = {};

/**
 * Synthesizes a realistic 24-hour ICU trajectory for any custom or new patient
 * consistent with PhysioNet / MIMIC feature distributions.
 */
export function generateSynthetic24HTrajectory(patientCode: string): HourlyObservationRecord[] {
  const code = patientCode.toUpperCase();
  if (PATIENT_HOURLY_DATASET[code]) return PATIENT_HOURLY_DATASET[code];
  if (DYNAMIC_PATIENT_HISTORIES[code]) return DYNAMIC_PATIENT_HISTORIES[code];

  const seed = code.split('').reduce((acc, c) => acc + c.charCodeAt(0), 0);
  const isDecomp = seed % 3 === 0;
  const isShock = seed % 7 === 0;

  const records: HourlyObservationRecord[] = [];
  const baseHr = isShock ? 115 : isDecomp ? 95 : 75;
  const baseSbp = isShock ? 90 : isDecomp ? 110 : 125;
  const baseLactate = isShock ? 3.5 : isDecomp ? 2.0 : 1.1;

  for (let h = 1; h <= 24; h++) {
    const progress = h / 24;
    const hr = Math.round(baseHr + (isDecomp ? progress * 25 : (h % 3) * 2 - 2));
    const sbp = Math.round(baseSbp - (isDecomp ? progress * 20 : 0));
    const dbp = Math.round(sbp * 0.6);
    const map = Math.round(dbp + (sbp - dbp) / 3);
    const lactate = Number((baseLactate + (isDecomp ? progress * 2.2 : 0) + ((h % 4) === 0 ? 0.1 : 0)).toFixed(2));
    const temp = Number((36.8 + (isDecomp ? progress * 1.8 : 0)).toFixed(1));
    const resp = Math.round(16 + (isDecomp ? progress * 10 : 0));
    const o2sat = Math.round(98 - (isDecomp ? progress * 7 : 0));

    records.push({
      HR: hr,
      O2Sat: o2sat,
      Temp: temp,
      SBP: sbp,
      MAP: map,
      DBP: dbp,
      Resp: resp,
      EtCO2: Math.round(38 - (isDecomp ? progress * 10 : 0)),
      BaseExcess: Number((-1.0 - (isDecomp ? progress * 4.0 : 0)).toFixed(1)),
      HCO3: Number((24.0 - (isDecomp ? progress * 5.0 : 0)).toFixed(1)),
      FiO2: isShock ? 0.5 : 0.21,
      pH: Number((7.40 - (isDecomp ? progress * 0.12 : 0)).toFixed(2)),
      PaCO2: 38,
      SaO2: o2sat,
      AST: 28,
      BUN: Math.round(16 + (isDecomp ? progress * 12 : 0)),
      Alkalinephos: 75,
      Calcium: 8.8,
      Chloride: 102,
      Creatinine: Number((1.0 + (isDecomp ? progress * 1.2 : 0)).toFixed(2)),
      Bilirubin_direct: null,
      Glucose: Math.round(110 + (isDecomp ? progress * 50 : 0)),
      Lactate: lactate,
      Magnesium: 2.0,
      Phosphate: 3.2,
      Potassium: 4.1,
      Bilirubin_total: 0.8,
      TroponinI: null,
      Hct: 38.0,
      Hgb: 12.5,
      PTT: 30.0,
      WBC: Number((8.0 + (isDecomp ? progress * 10.0 : 0)).toFixed(1)),
      Fibrinogen: 250,
      Platelets: Math.round(240 - (isDecomp ? progress * 80 : 0)),
      Age: 65,
      Gender: 1,
      Unit1: 1,
      Unit2: 0,
      HospAdmTime: -8,
      ICULOS: h,
      SepsisLabel: (isDecomp && h >= 20) || isShock ? 1 : 0,
    });
  }

  DYNAMIC_PATIENT_HISTORIES[code] = records;
  return records;
}

/**
 * Retrieves the complete longitudinal hourly history array for a patient.
 * If not in the pre-compiled cohort, dynamically generates a medically consistent 24H history.
 */
export function getPatientHourlyHistory(patientCode: string): HourlyObservationRecord[] {
  const normalized = patientCode.toUpperCase();
  if (PATIENT_HOURLY_DATASET[normalized]) {
    return PATIENT_HOURLY_DATASET[normalized];
  }
  return generateSynthetic24HTrajectory(patientCode);
}

/**
 * Returns the latest (hour 24 or current) observation record for a patient
 */
export function getPatientLatestObservation(patientCode: string): HourlyObservationRecord {
  const history = getPatientHourlyHistory(patientCode);
  return history[history.length - 1];
}

/**
 * Lists all patient codes available in the longitudinal dataset
 */
export function getAllDatasetPatientCodes(): string[] {
  return Object.keys(PATIENT_HOURLY_DATASET);
}
